/*
 * A157807  Numerators of fractions arranged in "antidiagonal boustrophedon"
 *          ordering with equivalent fractions removed: (1/1, 2/1, 1/2, 1/3,
 *          3/1, 4/1, 3/2, 2/3, 1/4, 1/5, 5/1, 6/1, 5/2, ...).
 * https://oeis.org/A157807
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, frac
 * Formula:   a(n) is generated by taking all reduced fractions m/(S‑m) with m
 *            + (S‑m) = S in boustrophedon antidiagonal order. For each
 *            integer S ≥ 2 the numerators m are listed: • if S is even –
 *            ascending 1, 2, …, S‑1 • if S is odd – descending S‑1, …, 1 Only
 *            pairs with gcd(m,S‑m) = 1 are kept. This function...
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   gcd
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stddef.h>
#include "../utils/gcd.h"

seq_t a(idx_t n)
{
    if (n == 0U) return (seq_t)0;   /* undefined for n = 0, harmless return */

    idx_t count = 0U;

    for (idx_t S = 2U; ; ++S) {
        bool ascending = (S % 2U == 0U);

        if (ascending) {
            for (idx_t m = 1U; m < S; ++m) {
                if (gcd((seq_t)m, (seq_t)(S - m)) == (seq_t)1U) {
                    ++count;
                    if (count == n) return (seq_t)m;
                }
            }
        } else {
            for (idx_t m = S - 1U; m >= 1U; --m) {
                if (gcd((seq_t)m, (seq_t)(S - m)) == (seq_t)1U) {
                    ++count;
                    if (count == n) return (seq_t)m;
                }
            }
        }
    }
}
